import sqlite3, json
conn = sqlite3.connect('/workspace/world.db')
conn.row_factory = sqlite3.Row

# Search for item ITEM-63F395 or 63F395 in order_items
print('=== Searching order_items ===')
for r in conn.execute('SELECT * FROM order_items'):
    cols = r.keys()
    row_dict = {c: r[c] for c in cols}
    if '63F395' in json.dumps(row_dict):
        print(row_dict)

# Search in rt_variants
print('=== Searching rt_variants ===')
for r in conn.execute('SELECT * FROM rt_variants'):
    cols = r.keys()
    row_dict = {c: r[c] for c in cols}
    if '63F395' in json.dumps(row_dict):
        print(row_dict)

# General search across all tables
print('=== All tables ===')
tables = [r[0] for r in conn.execute(\"SELECT name FROM sqlite_master WHERE type='table'\").fetchall()]
print(tables)

for t in tables:
    for r in conn.execute(f'SELECT * FROM {t}'):
        cols = r.keys()
        row_dict = {c: r[c] for c in cols}
        if '63F395' in json.dumps(row_dict):
            print(f'Found in {t}:', row_dict)
conn.close()
